using System;
using System.Linq;
using System.Collections.Generic;
using DealNight.Core;
namespace DealNight.Tests {
 public static class RuleChecks {
  static void Check(bool yes,string message){if(!yes)throw new Exception(message);}
  static void Do(Game g,Command c){string e;Check(g.Execute(c,out e),e??"Command failed");}
  static Game Blank(){var g=new Game(2,1);foreach(var p in g.Players){p.Hand.Clear();p.Bank.Clear();p.Sets.Clear();}g.Deck.Clear();g.Discard.Clear();g.Deck.AddRange(g.Cards.Select(c=>c.Id));return g;}
  static int Give(Game g,int p,Kind k,int value=-1){int id=g.Deck.First(i=>g.Cards[i].Kind==k&&(value<0||g.Cards[i].Value==value));g.Deck.Remove(id);g.Players[p].Hand.Add(id);return id;}
  static int Cash(Game g,int p,int v){int id=Give(g,p,Kind.Money,v);g.Players[p].Hand.Remove(id);g.Players[p].Bank.Add(id);return id;}
  static PropertySet Set(Game g,int p,Group color,int count){var s=new PropertySet{Id=100+g.Players.Sum(x=>x.Sets.Count),Color=color};g.Players[p].Sets.Add(s);foreach(int id in g.Deck.Where(i=>g.Cards[i].Kind==Kind.Property&&g.Cards[i].Colors[0]==color).Take(count).ToArray()){g.Deck.Remove(id);s.Cards.Add(id);}return s;}
  static void Allow(Game g){while(g.Phase==Phase.Reaction)Do(g,new Command(Op.Pass,g.DecisionPlayer));}
  public static void Deck(){var d=Catalog.Create(true);Check(d.Count==110,"110 including references");Check(d.Count(c=>c.Kind==Kind.Reference)==4,"four references");Check(d.Count(c=>c.Property)==39,"39 properties/wilds");Check(d.Count(c=>c.Kind==Kind.Rent)==13,"13 rent");Check(d.Count(c=>c.Kind==Kind.Money)==20,"20 money");Check(d.Where(c=>c.Kind==Kind.Money).Sum(c=>c.Value)==57,"57M");Check(d.Count(c=>c.Kind==Kind.PassGo)==10,"10 pass go");Check(d.Count(c=>c.Kind==Kind.Wild)==11,"11 wilds");Check(d.Select(c=>c.Id).Distinct().Count()==110,"unique IDs");}
  public static void Initial(){var g=new Game(5,3);Check(g.Players[0].Hand.Count==7&&g.Players.Skip(1).All(p=>p.Hand.Count==5),"initial deal and draw");Check(g.Deck.Count==79,"initial remainder");g.AssertConservation();var b=Blank();Do(b,new Command(Op.End,0));Check(b.Players[1].Hand.Count==5,"empty hand draws five");}
  public static void PlayLimit(){var g=Blank();for(int i=0;i<4;i++)Give(g,0,Kind.Money);for(int i=0;i<3;i++)Do(g,g.Legal(0).First(c=>c.Op==Op.Bank));Check(g.Remaining==0,"budget");Check(!g.Legal(0).Any(c=>c.Op==Op.Bank),"fourth denied");string e;Check(!g.Execute(new Command(Op.Bank,0,g.Players[0].Hand[0]),out e),"validator denies fourth");}
  public static void HandLimit(){var g=Blank();for(int i=0;i<10;i++)Give(g,0,Kind.PassGo);Do(g,new Command(Op.End,0));Check(g.Phase==Phase.Discarding,"discard phase");for(int i=0;i<3;i++)Do(g,g.Legal(0).First());Check(g.Current==1&&g.Players[0].Hand.Count==7&&g.Discard.Count==3,"discard and next");}
  public static void Payment(){var g=Blank();int action=Give(g,1,Kind.House);g.Players[1].Hand.Remove(action);g.Players[1].Bank.Add(action);int debt=Give(g,0,Kind.DebtCollector);int hand=Give(g,1,Kind.Money,10);Do(g,new Command(Op.Play,0,debt){Target=1});Allow(g);string e;Check(!g.Execute(new Command(Op.Pay,1){Extras=new[]{hand}},out e),"cannot pay hand");Do(g,new Command(Op.Pay,1){Extras=new[]{action}});Check(g.Players[0].Bank.Contains(action),"bank action stays bank");Check(g.Players[1].Hand.Contains(hand),"hand untouched on insolvency");}
  public static void Overpay(){var g=Blank();int cash=Cash(g,1,10),debt=Give(g,0,Kind.DebtCollector);Do(g,new Command(Op.Play,0,debt){Target=1});Allow(g);string e;Check(!g.Execute(new Command(Op.Pay,1){Extras=new[]{cash,cash}},out e),"duplicate blocked");Do(g,new Command(Op.Pay,1){Extras=new[]{cash}});Check(g.BankTotal(0)==10&&g.BankTotal(1)==0,"no change");Check(g.Players[1].Overpaid==5&&g.Players[1].LargestOverpayment==5,"record payment excess");}
  public static void EmptyPayment(){var g=Blank();int debt=Give(g,0,Kind.DebtCollector);Do(g,new Command(Op.Play,0,debt){Target=1});Allow(g);Do(g,new Command(Op.Pay,1));Check(g.Phase==Phase.Playing,"empty payment resolves");}
  public static void Wildcards(){var g=Blank();var s=Set(g,0,Group.Brown,1);int id=g.Deck.First(i=>g.Cards[i].Kind==Kind.Wild&&g.Cards[i].Colors.Contains(Group.Brown)&&g.Cards[i].Value>0);g.Deck.Remove(id);g.Players[0].Hand.Add(id);Do(g,new Command(Op.Play,0,id){Color=Group.Brown,Set=s.Id});Check(g.Complete(s),"wild completes");Do(g,new Command(Op.Move,0,id){Color=Group.LightBlue});Check(!g.Complete(s)&&g.Remaining==1,"rotation costs one play");Check(!g.Legal(1).Any(c=>c.Op==Op.Move),"other player cannot move");}
  public static void Steals(){var g=Blank();var full=Set(g,1,Group.Brown,2);var loose=Set(g,1,Group.Red,1);int sly=Give(g,0,Kind.SlyDeal);Check(!g.Legal(0).Any(c=>c.Card==sly&&full.Cards.Contains(c.Take)),"full set protected");Do(g,new Command(Op.Play,0,sly){Target=1,Take=loose.Cards[0]});Allow(g);Check(g.Players[0].Sets.Any(s=>s.Color==Group.Red),"sly transfer");}
  public static void Swap(){var g=Blank();var a=Set(g,0,Group.Red,1);var b=Set(g,1,Group.Green,1);int give=a.Cards[0],take=b.Cards[0],f=Give(g,0,Kind.ForcedDeal);Do(g,new Command(Op.Play,0,f){Target=1,Give=give,Take=take});Allow(g);Check(g.Players[0].Sets.Any(s=>s.Cards.Contains(take))&&g.Players[1].Sets.Any(s=>s.Cards.Contains(give)),"swap ownership");}
  public static void BuildingsAndBreaker(){var g=Blank();var s=Set(g,0,Group.Brown,2);int h=Give(g,0,Kind.House),hotel=Give(g,0,Kind.Hotel);Check(!g.Legal(0).Any(c=>c.Card==hotel&&c.Op==Op.Play),"hotel needs house");Do(g,new Command(Op.Play,0,h){Set=s.Id,Color=s.Color});Do(g,new Command(Op.Play,0,hotel){Set=s.Id,Color=s.Color});Check(g.Rent(s)==9,"both rent bonuses");int breaker=Give(g,1,Kind.DealBreaker);Do(g,new Command(Op.End,0));Do(g,new Command(Op.Play,1,breaker){Target=0,Set=s.Id});Allow(g);Check(g.Players[1].Sets.Contains(s)&&s.House==h&&s.Hotel==hotel,"breaker transfers buildings");}
  public static void RentDouble(){var g=Blank();var s=Set(g,0,Group.Brown,2);int rent=g.Deck.First(i=>g.Cards[i].Kind==Kind.Rent&&g.Cards[i].Colors.Contains(Group.Brown)&&g.Cards[i].Colors.Length==2);g.Deck.Remove(rent);g.Players[0].Hand.Add(rent);int d1=Give(g,0,Kind.DoubleRent),d2=Give(g,0,Kind.DoubleRent);Do(g,new Command(Op.Play,0,rent){Set=s.Id,Extras=new[]{d1,d2}});Check(g.Remaining==0&&g.Pending.Amount==8,"double stack four times / three plays");}
  public static void Reactions(){var g=Blank();int debt=Give(g,0,Kind.DebtCollector),no1=Give(g,1,Kind.JustSayNo),no0=Give(g,0,Kind.JustSayNo),no2=Give(g,1,Kind.JustSayNo);Do(g,new Command(Op.Play,0,debt){Target=1});Do(g,new Command(Op.No,1,no1));Check(g.Pending.Cancelled&&g.DecisionPlayer==0,"first no");Do(g,new Command(Op.No,0,no0));Check(!g.Pending.Cancelled,"counter");Do(g,new Command(Op.No,1,no2));Allow(g);Check(g.Phase==Phase.Playing&&g.Remaining==2,"third no and reaction cost");}
  public static void Reshuffle(){var g=Blank();int pass=Give(g,0,Kind.PassGo);g.Discard.AddRange(g.Deck);g.Deck.Clear();Do(g,new Command(Op.Play,0,pass));Check(g.Players[0].Hand.Count==2&&g.Deck.Count==104,"reshuffle");g.AssertConservation();}
  public static void WinTiming(){var g=Blank();Set(g,0,Group.Brown,2);Set(g,0,Group.Utility,2);var blue=Set(g,1,Group.DarkBlue,2);int b=Give(g,0,Kind.DealBreaker);Do(g,new Command(Op.Play,0,b){Target=1,Set=blue.Id});Check(g.Winner==-1&&g.Phase==Phase.Reaction,"wait for reaction");Allow(g);Check(g.Winner==0&&g.Phase==Phase.GameOver,"win after resolution");}
  public static void Privacy(){var g=new Game(3,7);var o=g.Observe(1);Check(o.Hand.Length==5&&o.Players[0].HandCount==7,"only own hand and public counts");Check(typeof(Observation).GetField("Deck")==null,"no future deck");}
  public static void Birthday(){var g=new Game(3,8);int id=g.Cards.First(c=>c.Kind==Kind.Birthday).Id;foreach(var p in g.Players)p.Hand.Remove(id);g.Deck.Remove(id);g.Players[0].Hand.Add(id);Do(g,new Command(Op.Play,0,id));int n=0;while(g.Phase!=Phase.Playing){if(g.Phase==Phase.Reaction)Do(g,new Command(Op.Pass,g.DecisionPlayer));else{Do(g,new Command(Op.Pay,g.DecisionPlayer));n++;}}Check(n==2,"each opponent charged");}
  public static void Universal(){var g=Blank();int id=Give(g,0,Kind.Wild,0);Do(g,new Command(Op.Play,0,id){Color=Group.Brown});var s=g.Players[0].Sets.First();Check(g.Rent(s)==0&&!g.Assets(0).Contains(id),"universal alone no rent / payment");}
  public static void BuildingRestrictions(){var g=Blank();Set(g,0,Group.Railroad,4);Set(g,0,Group.Utility,2);int h=Give(g,0,Kind.House);Check(!g.Legal(0).Any(c=>c.Card==h&&c.Op==Op.Play),"no transit buildings");}
  public static void ExactDistribution(){var d=Catalog.Create();Kind[] kinds={Kind.Money,Kind.Property,Kind.Wild,Kind.Rent,Kind.PassGo,Kind.DebtCollector,Kind.Birthday,Kind.SlyDeal,Kind.ForcedDeal,Kind.DealBreaker,Kind.JustSayNo,Kind.House,Kind.Hotel,Kind.DoubleRent};int[] expected={20,28,11,13,10,3,3,3,3,2,3,3,2,2};for(int i=0;i<kinds.Length;i++)Check(d.Count(c=>c.Kind==kinds[i])==expected[i],"quantity "+kinds[i]);for(int i=0;i<10;i++)Check(d.Count(c=>c.Kind==Kind.Property&&c.Colors[0]==(Group)i)==Catalog.Sizes[i],"natural color quantity");Check(d.Count(c=>c.Kind==Kind.Wild&&c.Value==0)==2,"two universal wilds");}
  public static void ValuedWildBank(){var g=Blank();int w=Give(g,0,Kind.Wild,1);Do(g,new Command(Op.Bank,0,w));Check(g.Players[0].Bank.Contains(w)&&!g.Legal(0).Any(c=>c.Card==w),"B0965 valued wild bank permanent");}
  public static void PropertyPayment(){var g=Blank();var s=Set(g,1,Group.Brown,2);int id=s.Cards[0],debt=Give(g,0,Kind.DebtCollector);Do(g,new Command(Op.Play,0,debt){Target=1});Allow(g);Do(g,new Command(Op.Pay,1){Extras=s.Cards.ToArray()});Check(g.Players[0].Sets.Any(x=>x.Cards.Contains(id))&&!g.Players[0].Bank.Contains(id),"property destination");}
  public static void InsufficientSelectionRejected(){var g=Blank();int a=Cash(g,1,1);Cash(g,1,2);int debt=Give(g,0,Kind.DebtCollector);Do(g,new Command(Op.Play,0,debt){Target=1});Allow(g);string e;Check(!g.Execute(new Command(Op.Pay,1){Extras=new[]{a}},out e),"must pay all when insolvent");Check(g.BankTotal(1)==3,"rejection is atomic");}
  public static void RentTargets(){var g=Blank();var s=Set(g,0,Group.Red,1);int any=g.Deck.First(i=>g.Cards[i].Kind==Kind.Rent&&g.Cards[i].Colors.Length==10);g.Deck.Remove(any);g.Players[0].Hand.Add(any);Check(g.Legal(0).Where(c=>c.Card==any&&c.Op==Op.Play).All(c=>c.Target==1),"any rent targets one");int pair=g.Deck.First(i=>g.Cards[i].Kind==Kind.Rent&&g.Cards[i].Colors.Length==2&&!g.Cards[i].Colors.Contains(Group.Red));g.Deck.Remove(pair);g.Players[0].Hand.Add(pair);Check(!g.Legal(0).Any(c=>c.Card==pair&&c.Op==Op.Play),"rent must match own group");Check(g.Rent(s)==2,"red base rent");}
  public static void MultiTargetNo(){var g=new Game(3,33);foreach(var p in g.Players){p.Hand.Clear();p.Bank.Clear();p.Sets.Clear();}g.Deck.Clear();g.Deck.AddRange(g.Cards.Select(c=>c.Id));int b=Give(g,0,Kind.Birthday),n=Give(g,1,Kind.JustSayNo);Do(g,new Command(Op.Play,0,b));Do(g,new Command(Op.No,1,n));Do(g,new Command(Op.Pass,0));Check(g.Pending.Target==2&&!g.Pending.Cancelled,"No affects only its target");Allow(g);Do(g,new Command(Op.Pay,2));Check(g.Phase==Phase.Playing,"other target resolved");}
  public static void Consolidate(){var g=Blank();var a=Set(g,0,Group.Brown,1);var b=Set(g,0,Group.Brown,1);Do(g,new Command(Op.Move,0,b.Cards[0]){Color=Group.Brown,Set=a.Id});Check(g.Complete(a)&&g.Remaining==3,"normal cards consolidate freely");}
  public static void DormantBuildings(){var g=Blank();var s=Set(g,0,Group.Brown,2);int h=Give(g,0,Kind.House);Do(g,new Command(Op.Play,0,h){Set=s.Id,Color=s.Color});int debt=Give(g,1,Kind.DebtCollector);Do(g,new Command(Op.End,0));Do(g,new Command(Op.Play,1,debt){Target=0});Allow(g);Do(g,new Command(Op.Pay,0){Extras=new[]{s.Cards[0],h,s.Cards[1]}});Check(g.Players[1].Bank.Contains(h),"paid building becomes money");}
  public static void ResponsiveGrid(){foreach(int count in new[]{1,2,3,7,10,20,39,106})foreach(float width in new[]{220f,320f,720f,1280f,1920f})foreach(float height in new[]{80f,160f,300f}){var g=PresentationMath.Fit(count,width,height,205,142,1.15f);Check(g.Scale>0&&g.Columns*g.Rows>=count,"every tile assigned");for(int i=0;i<count;i++){float x=(i%g.Columns)*g.CellWidth+g.OffsetX,y=(i/g.Columns)*g.CellHeight+g.OffsetY;Check(x>=0&&y>=0&&x+205*g.Scale<=width+.01f&&y+142*g.Scale<=height+.01f,"tile stays within region");}}Check(PresentationMath.Fit(0,100,100,205,142).Scale==0,"empty grid");Check(PresentationMath.Fit(4,float.NaN,100,205,142).Scale==0,"unresolved geometry");Check(PresentationMath.Fit(3,400,200,205,142).Scale>PresentationMath.Fit(30,400,200,205,142).Scale,"grows when cards leave");}
  public static void PlayerIdentity(){Check(PresentationMath.PlayerName("  Jacob   Ferguson ")=="Jacob Ferguson","trim and collapse whitespace");Check(PresentationMath.PlayerName(" ")=="","blank rejected");Check(PresentationMath.PlayerName(new string('a',40)).Length==24,"name limit");var g=new Game(2,5,"Jacob");Check(g.Players[0].Name=="Jacob"&&g.History[0].StartsWith("Jacob started"),"initial turn uses supplied name");var y=new Game(2,5,"You");Check(y.History[0].StartsWith("You started"),"pronoun-safe wording");}
  public static void WildTransferAndRotate(){var g=Blank();var rail=Set(g,0,Group.Railroad,3);var utility=Set(g,1,Group.Utility,1);int wild=g.Deck.First(id=>g.Cards[id].Kind==Kind.Wild&&g.Cards[id].Colors.Length==2&&g.Cards[id].Colors.Contains(Group.Railroad)&&g.Cards[id].Colors.Contains(Group.Utility));g.Deck.Remove(wild);utility.Cards.Clear();g.Deck.AddRange(g.Cards.Where(c=>c.Kind==Kind.Property&&c.Colors[0]==Group.Utility).Select(c=>c.Id).Where(id=>!g.Deck.Contains(id)));utility.Cards.Add(wild);int sly=Give(g,0,Kind.SlyDeal);Do(g,new Command(Op.Play,0,sly){Target=1,Take=wild});Allow(g);Check(g.Remaining==2,"steal no extra play");Check(g.Players[0].Sets.Any(x=>x.Color==Group.Utility&&x.Cards.Contains(wild)),"received orientation retained");Do(g,new Command(Op.Move,0,wild){Color=Group.Railroad,Set=rail.Id});Check(g.Remaining==1&&g.Complete(rail),"rotate completes rail for one play");int cash=Give(g,0,Kind.Money);Do(g,new Command(Op.Bank,0,cash));Check(!g.Legal(0).Any(c=>c.Op==Op.Move&&c.Card==wild&&c.Color!=Group.Railroad),"cannot rotate with zero plays");}
  public static void PlacementDecisions(){var a=new PropertySet{Id=1,Color=Group.LightBlue,Cards=new List<int>{1,2}};var b=new PropertySet{Id=2,Color=Group.LightBlue,Cards=new List<int>{3}};Check(PlacementPolicy.AutomaticDestination(new[]{a,b},new[]{-1,1,2})==1,"unique completion preferred");b.Cards.Add(4);Check(PlacementPolicy.AutomaticDestination(new[]{a,b},new[]{-1,1,2})==-2,"competing completions ask");Check(PlacementPolicy.AutomaticDestination(new[]{a},new[]{-1,1})==1,"sole matching group auto");Check(PlacementPolicy.ReceivingGroup(new[]{b,a},Group.LightBlue).Id==1,"stable receive tie");}
  public static void SmartPayments(){var g=Blank();Set(g,1,Group.Red,2);var weak=Set(g,1,Group.Green,1);int debt=Give(g,0,Kind.DebtCollector);Do(g,new Command(Op.Play,0,debt){Target=1});Allow(g);var ai=new Computer(Difficulty.Normal,4);var pay=ai.Choose(g.Observe(1),g.Legal(1));Check(pay.Extras.Contains(weak.Cards[0]),"singleton preferred over sacrificing only developed set");Do(g,pay);var b=Blank();Set(b,1,Group.Brown,2);Cash(b,1,10);int d=Give(b,0,Kind.DebtCollector);Do(b,new Command(Op.Play,0,d){Target=1});Allow(b);var cash=ai.Choose(b.Observe(1),b.Legal(1));Check(cash.Extras.All(id=>b.Players[1].Bank.Contains(id)),"cash protects complete group even overpay");}
  public static void SameColorWildcardMoveIsFree(){var g=Blank();var natural=Set(g,0,Group.LightBlue,1);var other=Set(g,0,Group.LightBlue,0);int wild=g.Deck.First(id=>g.Cards[id].Kind==Kind.Wild&&g.Cards[id].Colors.Contains(Group.LightBlue));g.Deck.Remove(wild);other.Cards.Add(wild);for(int i=0;i<3;i++){int cash=Give(g,0,Kind.Money);Do(g,new Command(Op.Bank,0,cash));}Do(g,new Command(Op.Move,0,wild){Color=Group.LightBlue,Set=natural.Id});Check(g.Remaining==0&&natural.Cards.Contains(wild),"same-color regroup costs nothing at zero plays");}
  public static void OpponentIdentities(){var a=new Game(5,41,"Morgan");var b=new Game(5,41,"morgan");var names=a.Players.Skip(1).Select(p=>p.Name).ToArray();Check(names.Distinct().Count()==4&&!names.Any(n=>n.Equals("Morgan",StringComparison.OrdinalIgnoreCase)),"unique opponents exclude human name");Check(names.SequenceEqual(b.Players.Skip(1).Select(p=>p.Name)),"seeded names are reproducible");Check(!names.SequenceEqual(new Game(5,42,"Morgan").Players.Skip(1).Select(p=>p.Name)),"different game seeds vary names");var c=new Game(5,41,"Casey");Check(a.Deck.SequenceEqual(c.Deck)&&a.Players.Zip(c.Players,(x,y)=>x.Hand.SequenceEqual(y.Hand)).All(x=>x),"name selection cannot change dealt cards");}
  public static void AnimationSpeedSteps(){var speeds=PresentationOptions.Durations;Check(speeds.Length==5&&PresentationOptions.SpeedNames.Length==5,"five speeds");Check(speeds[0]==.25f&&speeds[4]==2.5f,"quarter to two and a half seconds");for(int i=1;i<5;i++)Check(Math.Abs(speeds[i]-speeds[i-1]-.5625f)<.0001f,"even duration spacing");Check(PresentationOptions.MigrateSpeed(3.25f)==4,"old slowest clamps");}

  public static void ContextPayment(){var g=Blank();Cash(g,1,10);Set(g,1,Group.Brown,2);Set(g,1,Group.Utility,2);Set(g,1,Group.Red,2);Set(g,1,Group.Railroad,1);var pink=Set(g,1,Group.Pink,1);Set(g,0,Group.Railroad,1);int birthday=Give(g,0,Kind.Birthday);Do(g,new Command(Op.Play,0,birthday));Allow(g);var pay=new Computer(Difficulty.Normal,0).Choose(g.Observe(1),g.Legal(1));Check(pay.Extras.SequenceEqual(new[]{pink.Cards[0]}),"prefer exact singleton to 10M, avoiding recipient color and full sets");Do(g,pay);Check(g.Players[1].Overpaid==0&&g.Players[0].Received==2,"payment statistics");}
  public static void GuidedTutorial(){
   var t=new TutorialSession("Learner");int actions=0,lessons=1,last=0;
   do {Check(t.World.Players.Count==2&&t.World.Players[1].Name=="Dr. Noisewater","fixed tutorial opponent");if(t.Lesson!=last){lessons++;last=t.Lesson;}
    var c=t.Expected();Check(t.Matches(c),"tutorial accepts expected action");Do(t.World,c);t.World.AssertConservation();actions++;
    if(t.Lesson==0&&t.StepIndex==2)Check(t.World.Remaining==0&&t.World.CompleteCount(0)==1,"basic set lesson");
    if(t.Lesson==1&&t.StepIndex==1)Check(t.World.Players[0].Hand.Count==5,"empty hand tutorial draws five");
    if(t.Lesson==6&&t.StepIndex==1)Check(t.World.Rent(t.World.Players[0].Sets[0])==9,"tutorial building bonuses");
    if(t.Lesson==9&&t.StepIndex==4)Check(t.World.CompleteCount(0)==1,"tutorial No chain protects set");
   }while(t.Next());
   Check(lessons==TutorialSession.LessonCount&&actions>40&&t.World.Winner==0,"all tutorial scenes end with victory");Console.WriteLine("Tutorial actions: "+actions);
  }
  public static void ChargeRecommendations(){
   var g=Blank();Set(g,0,Group.DarkBlue,1);Cash(g,1,1);Set(g,1,Group.Orange,1);int rent=g.Deck.First(i=>g.Cards[i].Kind==Kind.Rent&&g.Cards[i].Colors.Length==10);g.Deck.Remove(rent);g.Players[0].Hand.Add(rent);var c=g.Legal(0).First(x=>x.Card==rent&&x.Op==Op.Play);
   Check(ChargeAdvice.Amount(g,c)==3&&ChargeAdvice.Outlook(g,1,3).Contains("property/building"),"bank shortfall advice");Do(g,c);Check(g.Pending.Card==rent&&!g.Pending.AllOpponents,"incoming identifies exact rent card and scope");
   Check(Catalog.Describe(g.Cards[rent]).Contains("ONE opponent"),"any-color scope explicit");Check(Catalog.Describe(g.Cards.First(x=>x.Kind==Kind.Rent&&x.Colors.Length==2)).Contains("ALL opponents"),"paired scope explicit");
  }
  public static void ChargeTargetRanking(){
   var g=new Game(3,80);foreach(var p in g.Players){p.Hand.Clear();p.Bank.Clear();p.Sets.Clear();}g.Deck.Clear();g.Deck.AddRange(g.Cards.Select(c=>c.Id));Set(g,0,Group.DarkBlue,1);Cash(g,1,3);Cash(g,2,1);Set(g,2,Group.Orange,1);
   int rent=g.Deck.First(i=>g.Cards[i].Kind==Kind.Rent&&g.Cards[i].Colors.Length==10);g.Deck.Remove(rent);g.Players[0].Hand.Add(rent);var choices=g.Legal(0).Where(c=>c.Card==rent&&c.Op==Op.Play).ToArray();
   Check(choices.OrderByDescending(c=>ChargeAdvice.Score(g,c)).First().Target==2,"prefer collectible bill likely to transfer property");
   var pair=g.Cards.First(c=>c.Kind==Kind.Rent&&c.Colors.Length==2&&c.Colors.Contains(Group.DarkBlue));g.Deck.Remove(pair.Id);g.Players[0].Hand.Add(pair.Id);Do(g,g.Legal(0).First(c=>c.Card==pair.Id&&c.Op==Op.Play));
   Check(g.Pending.AllOpponents&&g.Pending.Card==pair.Id&&g.Observe(0).Pending.AllOpponents,"paired rent metadata preserved for reactions");
  }
  public static void RunAll(){foreach(var method in typeof(RuleChecks).GetMethods(System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.Static).Where(m=>m.Name!="RunAll")){method.Invoke(null,null);Console.WriteLine("PASS "+method.Name);}}
 }
